.sprite-higgsfield-error {
  width: 256px;
  height: 256px;
  background: url('higgsfield-error.png') left center;
  background-size: 9216px 256px;
  animation: sprite-higgsfield-error-play 6.00s steps(36) infinite;
}

@keyframes sprite-higgsfield-error-play {
  to { background-position: right center; }
}
